define([],function(){return{init:async function(c){var s=document.getElementById("aiel-generation-progress");try{for(var i=0;i<100;i++){var b=new URLSearchParams({id:c.id,job:c.job,sesskey:c.sesskey,step:1}),r=await fetch(c.url,{method:"POST",credentials:"same-origin",body:b});if(!r.ok)throw Error("request");var x=await r.json();if("succeeded"===x.status&&x.version){var u=c.audioenabled?c.audiourl+"?id="+encodeURIComponent(c.id)+"&version="+encodeURIComponent(x.version):c.lessonurl+"&version="+encodeURIComponent(x.version);window.location.assign(u);return}if("failed"===x.status)throw Error("failed");s.textContent=c.working+" ("+Math.min(3,x.stage+1)+"/3)";if("running"===x.status)await new Promise(function(t){setTimeout(t,5e3)})}throw Error("limit")}catch(e){s.textContent=c.failed,s.className="alert alert-warning"}}}});
